CREATE TABLE IF NOT EXISTS "staff" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int UNIQUE,
  "staff_code" varchar(30) UNIQUE,
  "full_name" varchar(255) NOT NULL,
  "hire_date" date,
  "employment_status" varchar(30) NOT NULL DEFAULT 'ACTIVE',
  "note" text,
  "created_at" timestamp
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'fk_staff_users'
  ) THEN
    ALTER TABLE "staff" ADD CONSTRAINT fk_staff_users FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
  END IF;
END $$;
